col.right = '#006d2c';

% condition colors
col.rest = '#264653';
col.stand_up = '#fdbf6f';
col.balance = '#1f78b4';
col.walk = '#a6cee3';
col.right_90 = '#b2df8a';
col.right_180 = '#33a02c';
col.left_90 = '#fb9a99';
col.left_180 = '#e31a1c';
