col.ramp_down = '#6a3d9a';

%% Handle the acquisition index from the subject and session numbers using the info file
% Every subject and session combination can have multiple acquisition IDs, which are stored in the info.xlsx file. 
% This section reads the info file and extracts the corresponding acquisition IDs for the specified subject and session.

info = readcell(fullfile(rawDataDir, 'info.xlsx')); % read as cell array to handle mixed data types
info = cell2table(info(2:end, :), 'VariableNames', info(1, :)); % convert to table for easier manipulation
variableNames = string(info.Properties.VariableNames);

subjectColumn = find(strcmpi(variableNames, 'subject'), 1);
sessionColumn = find(strcmpi(variableNames, 'session'), 1);
idColumn = find(strcmpi(variableNames, 'id'), 1);
eventsSourceColumn = find(strcmpi(variableNames, 'eventsSource'), 1);
syncSourceColumn = find(strcmpi(variableNames, 'syncSource'), 1);
if isempty(subjectColumn) || isempty(sessionColumn) || isempty(idColumn) || isempty(eventsSourceColumn)
    error('The info.xlsx file must contain columns named "subject", "session", "id", "eventsSource", and "syncSource".');
end

rowMask = string(info{:, subjectColumn}) == subject & string(info{:, sessionColumn}) == session;
if ~any(rowMask)
    error('No rows found for subject %s and session %s.', subject, session);
end

idText = strjoin(string(info{rowMask, idColumn}), ';');
idTokens = regexp(idText, '\d+', 'match');
idxs = str2double(idTokens);
if isempty(idxs) || any(isnan(idxs))
    error('Invalid id value for subject %s and session %s: %s.', subject, session, idText);
end
idxs = unique(idxs, 'stable'); % multiple acquisitions can be present, keep unique values
eventsSource = string(info{rowMask, eventsSourceColumn});
syncSource = string(info{rowMask, syncSourceColumn});

%% Analysis pipeline for each subject and session combination (one or more acquisition IDs)
% Get the events data (from the "coordinator" field) to separate the data into different phases (e.g., walking, etc.) and extract the metric values for each phase.
% Get the tip loadcell data, extract the metric values for each phase
% Repeat for the handle loadcell, ppg, and ups data for each phase

events = import_events(campaignDir,idxs, eventsSource, syncSource);
[tip_left, tip_right] = import_h5_data(fullfile(rawDataDir, "crutch"), idxs, "tip_loadcell", false);
[handle_left, handle_right] = import_h5_data(fullfile(rawDataDir, "crutch"), idxs, "handle_loadcell", false);
[ppg_left, ppg_right] = import_h5_data(fullfile(rawDataDir, "crutch"), idxs, "ppg", false);
[ups_left, ups_right] = import_h5_data(fullfile(rawDataDir, "crutch"), idxs, "ups", false);


