%% Data analysis and metrics extraction

% Tip loadcell data analysis
% HX711 loadcell amplifier introduce some unwanted spikes in the force signal. We remove them with a custom filter
tip_left.force = filterLoadcell(tip_left.force);
tip_right.force = filterLoadcell(tip_right.force);


% DA SISTEMARE:
% Bisogna dividere per eventi
% Analizzare i picchi
% Rms
% Simmetrie varie
t = (tip_left.timestamp-tip_left.timestamp(1))*10^-9;
[left_peaks, left_locs, left_widths, left_proms] = findpeaks(tip_left.force,t,'MinPeakProminence',prctile(tip_left.force,60),'Annotate','extents');

t = (tip_right.timestamp-tip_left.timestamp(1))*10^-9;
[right_peaks, right_locs, right_widths, right_proms] = findpeaks(tip_right.force,t,'MinPeakProminence',prctile(tip_right.force,60),'Annotate','extents');

% rimuovo i picchi trovati sugli spikes controllando
% l'ampiezza del picco. Se minore di 0.1 s non ha senso di
% esistere
threshold_width = 0.1; % seconds
left_peaks(left_widths<threshold_width) = [];
left_locs(left_widths<threshold_width) = [];
left_proms(left_widths<threshold_width) = [];
left_widths(left_widths<threshold_width) = [];

right_peaks(right_widths<threshold_width) = [];
right_locs(right_widths<threshold_width) = [];
right_proms(right_widths<threshold_width) = [];
right_widths(right_widths<threshold_width) = [];

results.("left").peaks.mean = mean(left_peaks);
results.("left").peaks.rms = rms(left_peaks);
results.("left").peaks.std = std(left_peaks);

results.("left").prominences.mean = mean(left_proms);
results.("left").prominences.rms = rms(left_proms);
results.("left").prominences.std = std(left_proms);

results.("left").widths.mean = mean(left_widths);
results.("left").widths.rms = rms(left_widths);
results.("left").widths.std = std(left_widths);

results.("right").peaks.mean = mean(right_peaks);
results.("right").peaks.rms = rms(right_peaks);
results.("right").peaks.std = std(right_peaks);

results.("right").prominences.mean = mean(right_proms);
results.("right").prominences.rms = rms(right_proms);
results.("right").prominences.std = std(right_proms);

results.("right").widths.mean = mean(right_widths);
results.("right").widths.rms = rms(right_widths);
results.("right").widths.std = std(right_widths);


